WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_rank_average'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '平均数排序', 'kp-xingce-data-rank-average', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "平均数排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "多个分式 (A/B) 大小的综合排序，极致的选项排除战术。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "要求对四个主体（如：四个城市的房屋均价 = 销售额/面积）进行排序。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝对不能去硬算四个除法竖式！遵循选项定位法。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出四个待排序的分数式 A/B] --> B[第一眼找极端值: 有没有分子极大且分母极小的项?]\nB -- 有 --> C[该项定为第一名, 去选项里排除掉不符合的]\nB -- 没有 --> D[观察 ABCD 选项的排列组合]\nC --> D\nD --> E[找选项分歧点: 比如选项A说 ②>③, 选项B说 ③>②]\nE --> F[把 ② 和 ③ 这两个分数单拎出来, 用倍数关系比大小]\nF --> G[验证成功, 直接锁定唯一选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲(500/10)、乙(600/15)、丙(400/8)、丁(800/18)。按从大到小排序。选项：A. 丁>甲>丙>乙  B. 丙>甲>丁>乙  C. 丁>丙>甲>乙  D. 丙>甲>乙>丁"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看极端项和选项：乙(600/15=40)，显然比较小，选项最后都是乙，不用管了。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找分歧点：看老大是谁？选项争论在于 丁 和 丙 谁第一。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "单独比 丁 和 丙：丁=800/18，丙=400/8。丙的分子 400 翻倍是 800，但分母 8 翻倍才 16。说明丙放大到同样的分子时分母更小，所以 丙分数 > 丁分数。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "排除项：排掉 A 和 C，只剩 B 和 D。两者区别在最后 丁 和 乙 谁垫底。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比 丁 和 乙：丁(800/18 ≈ 44+)，乙(40)。显然 丁 > 乙。选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死板列式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生的草稿纸上齐刷刷列了 4 个除法竖式，算出 50, 40, 50, 44.4，甚至还要算小数。这在考场上属于严重的时间浪费。利用分数性质（横向翻倍比对）远比算除法快。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "强化自己的选项拆解能力。把一道四排四的题，降维成两道两两相比的分数题。"}]}]}$$ AS jsonb), NULL, '平均数排序的核心考点与实战推导。', category_node.id, CAST('["资料分析", "平均数排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_average", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
